import assert from 'node:assert/strict';
import fs from 'node:fs';
import path from 'node:path';
import { writeLocalApiTokenFile } from '../../lib/local-api.js';

export async function verifyPanelFeedbackBrowser({ out, cdp, evaluate, click, wait, chooseToken, report, save,
  dimensions, measure, capture, restart }) {
  const result = report.panelFeedback = { status: 'running', checks: [], actualPaidCalls: 0 };
  const storageKey = 'iris.workbench.session.v0', config = path.join(out, 'feedback-providers.json');
  fs.writeFileSync(config, JSON.stringify({ providers: [], assignments: {} }) + '\n', { mode: 0o600 });
  let session = await restart(config), tokenCount = 0;
  const check = async (name, expression) => { assert.equal(await evaluate(expression), true, name); result.checks.push(name); save(); };
  const field = async (selector, value) => evaluate(`(()=>{const n=document.querySelector(${JSON.stringify(selector)});n.value=${JSON.stringify(value)};n.dispatchEvent(new Event('input',{bubbles:true}));n.dispatchEvent(new Event('change',{bubbles:true}));})()`);
  const connected = () => evaluate("document.querySelector('#connection').hidden&&!document.querySelector('#providers-tab').hidden&&!document.querySelector('#connection-new').disabled");
  const tokenFile = () => {
    const file = path.join(out, 'feedback-token-' + ++tokenCount); writeLocalApiTokenFile(file, session.accessToken, path.join(out, 'core')); return file;
  };
  await cdp('Page.navigate', { url: session.origin + '/' });
  await wait(() => evaluate("Boolean(document.documentElement.dataset.theme)"), 'feedback login mount');
  await chooseToken(tokenFile()); await wait(connected, 'feedback owner login');
  await check('appearance is the only theme entry and removed accent choices are absent', "!document.querySelector('#theme')&&!document.querySelector('#appearance-accent')&&document.querySelectorAll('#appearance-theme option').length===3&&document.documentElement.dataset.accent==='iris'");
  await click('#appearance-open'); await field('#appearance-theme','dark');
  await check('the unified appearance entry switches to dark immediately', "document.documentElement.dataset.theme==='dark'");
  await field('#appearance-theme','system');
  await cdp('Emulation.setEmulatedMedia',{features:[{name:'prefers-color-scheme',value:'dark'}]});
  await wait(()=>evaluate("document.documentElement.dataset.theme==='dark'"),'system dark media event');
  await check('system appearance follows the real browser media preference', "document.documentElement.dataset.theme==='dark'");
  await cdp('Emulation.setEmulatedMedia',{features:[{name:'prefers-color-scheme',value:'light'}]});
  await wait(()=>evaluate("document.documentElement.dataset.theme==='light'"),'system light media event');
  await check('system appearance updates when the browser preference changes', "document.documentElement.dataset.theme==='light'");
  await field('#appearance-theme','light'); await capture('appearance-unified'); await click('#appearance-close');
  await cdp('Emulation.setEmulatedMedia',{features:[]});
  await click('#connections-tab');
  await check('connections open as a compact overview with help folded and no empty form', "!document.querySelector('#connections-overview').hidden&&document.querySelector('#connection-editor').hidden&&!document.querySelector('#connection-help').open");
  await click('#connections-tab'); await click('#connection-new');
  result.observations = await evaluate("({newConnectionFocus:document.activeElement.id==='connection-name',newConnectionFeedback:!document.querySelector('#connections-feedback').hidden})");
  await click('#providers-tab'); await wait(() => evaluate("!document.querySelector('#provider-new').disabled"), 'feedback provider overview');
  await check('provider overview keeps its empty editor out of the first screen', "!document.querySelector('#providers-overview').hidden&&document.querySelector('#provider-editor').hidden");
  await click('#provider-new');
  await click('[data-provider-view="models"]'); await click('#provider-save');
  await check('invalid required connection fields reveal the correct section before browser focus', "!document.querySelector('#provider-view-connection').hidden&&document.activeElement.id==='provider-name'");
  await field('#provider-preset', 'comfyui');
  Object.assign(result.observations, await evaluate(`({comfyBadge:!!document.querySelector('#provider-comfy-mode')&&!document.querySelector('#provider-comfy-mode').hidden,comfyAnimations:document.querySelector('.provider-editor').getAnimations({subtree:true}).map(animation=>animation.animationName),savedLogin:sessionStorage.getItem(${JSON.stringify(storageKey)})!==null})`));
  await cdp('Page.reload');
  await wait(() => evaluate("Boolean(document.documentElement.dataset.theme)"), 'feedback reload mount');
  if (result.observations.savedLogin) await wait(connected, 'retained login validates after reload');
  result.observations.reloadConnected = await connected(); save();
  assert(result.observations.newConnectionFocus && result.observations.newConnectionFeedback, 'new connection must visibly prepare and focus its draft');
  assert(result.observations.comfyBadge && result.observations.comfyAnimations.includes('comfy-provider-sweep'), 'provider switch must have its own one-shot accent');
  assert(result.observations.savedLogin && result.observations.reloadConnected, 'successful login must survive same-tab refresh');
  result.checks.push('new connection focuses its draft, provider switch animates, and same-tab login survives refresh');
  await check('owner Token stays out of URL, form and persistent localStorage', `!location.search&&!location.hash&&!document.querySelector('#token').value&&Object.keys(localStorage).every(key=>key==='iris.panel.appearance.v0')&&Object.keys(sessionStorage).every(key=>key===${JSON.stringify(storageKey)})`);
  assert(report.requests.filter(item=>item.url.startsWith(session.origin)).every(item=>item.method==='GET'), 'login, switch, new draft and refresh must not write');
  result.checks.push('login, new draft, mode switch and refresh only read the service'); save();

  await click('#connections-tab');
  await check('connection page explains all three MCP setup steps and the actual running HTTP endpoint', "document.querySelectorAll('.connection-guide li').length===3&&document.querySelector('#connection-service-note').textContent.includes(location.origin+'/mcp')&&document.querySelector('#connection-service-note').textContent.includes('不会自动配置或启动客户端')");
  const writesBefore = report.requests.filter(item=>item.method==='POST').length;
  await click('#connection-new'); await field('#connection-name', 'Feedback connection'); await click('#connection-save');
  await wait(() => evaluate("document.querySelectorAll('#connections-list .connection-item').length===1&&!document.querySelector('#connection-save').disabled"), 'actual connection creation');
  await click('#connection-export-button');
  await wait(() => evaluate("!document.querySelector('#connection-export-result').hidden"), 'actual connection export');
  await check('created connection exports usable MCP configuration only after saving', "!!JSON.parse(document.querySelector('#connection-configuration').value).mcpServers.iris.command&&document.querySelector('#connection-state').textContent==='尚未使用'");
  await check('stdio instructions explain client-launched command and args', "document.querySelector('#connection-transport-note').textContent.includes('command / args')");
  assert.equal(report.requests.filter(item=>item.method==='POST').length-writesBefore,2);
  await dimensions(390); await click('#connection-new');
  await check('mobile new connection reveals the name and retains the saved record', "document.activeElement.id==='connection-name'&&document.querySelector('#connection-name').getBoundingClientRect().top>=0&&document.querySelector('#connection-name').getBoundingClientRect().bottom<=innerHeight&&document.querySelectorAll('#connections-list .connection-item').length===1&&document.querySelector('#connection-name').value===''");
  await measure('connection-new-390'); await capture('connection-new-390');
  assert.equal(report.requests.filter(item=>item.method==='POST').length-writesBefore,2,'preparing another draft does not create another connection');
  await click('#connection-back'); await click('#connections-list .connection-item'); await field('#connection-transport','http'); await click('#connection-export-button');
  await wait(()=>evaluate("!document.querySelector('#connection-export-result').hidden"),'HTTP configuration export');
  await check('HTTP instructions and exported endpoint match the running MCP service and use a separate credential', `(()=>{const cfg=JSON.parse(document.querySelector('#connection-configuration').value).mcpServers.iris;return cfg.url===location.origin+'/mcp'&&cfg.headers.Authorization!=='Bearer '+sessionStorage.getItem(${JSON.stringify(storageKey)})&&document.querySelector('#connection-transport-note').textContent.includes('专属密钥')})()`);
  const beforeCancel=report.requests.filter(item=>item.method==='POST').length;
  await click('[data-connection-view="details"]'); await click('#connection-delete');
  await check('deletion explicitly confirms revoked access and retained user work', "!document.querySelector('#connection-delete-confirm').hidden&&document.querySelector('#connection-export-result').hidden&&document.querySelector('#connection-delete-confirm').textContent.includes('作品、任务')");
  await click('#connection-delete-no'); assert.equal(report.requests.filter(item=>item.method==='POST').length,beforeCancel);
  await check('canceling deletion keeps the connection without writing', "document.querySelectorAll('#connections-list .connection-item').length===1&&document.querySelector('#connection-delete-confirm').hidden&&!document.querySelector('#connection-delete').hidden");
  await click('#connection-back');
  await check('a short mobile overview keeps navigation in one compact row instead of stretching the header', "document.querySelector('.app-sidebar').getBoundingClientRect().height<=72&&getComputedStyle(document.querySelector('#recent-panel')).display==='none'");
  await capture('connection-overview-390'); await click('#connections-list .connection-item'); await click('[data-connection-view="details"]');
  await click('#connection-delete'); await click('#connection-delete-yes');
  await wait(()=>evaluate("document.querySelectorAll('#connections-list .connection-item').length===0&&!document.querySelector('#connection-new').disabled"),'active grant deletion');
  await check('deleting an active connection removes it and clears configuration previews', "!document.querySelector('#connections-empty').hidden&&document.querySelector('#connection-export').hidden&&document.querySelector('#connection-configuration').value===''");
  await click('#connection-new'); await field('#connection-name','Revoked then deleted'); await click('#connection-save');
  await wait(()=>evaluate("document.querySelectorAll('#connections-list .connection-item').length===1&&!document.querySelector('#connection-save').disabled"),'second connection creation');
  await click('[data-connection-view="details"]'); await click('#connection-revoke'); await click('#connection-revoke-yes');
  await wait(()=>evaluate("document.querySelector('#connection-state').textContent==='已撤销'&&!document.querySelector('#connection-delete').disabled"),'revoke before delete');
  await check('a revoked connection retains a working delete action', "!document.querySelector('#connection-revoke-section').hidden&&!document.querySelector('#connection-delete').hidden&&document.querySelector('#connection-revoke').hidden");
  await click('#connection-delete'); await click('#connection-delete-yes');
  await wait(()=>evaluate("document.querySelectorAll('#connections-list .connection-item').length===0&&!document.querySelector('#connection-new').disabled"),'revoked grant deletion');
  result.checks.push('both active and previously revoked grants can be removed through the production UI'); save();
  await dimensions(1366,900); await click('#providers-tab');
  await wait(() => evaluate("!document.querySelector('#provider-new').disabled"), 'supplier settings reread');
  await click('#provider-new'); await field('#provider-preset','comfyui');
  await check('ComfyUI preset shows its badge and workflow controls', "!document.querySelector('#provider-comfy-mode').hidden&&document.querySelector('.provider-editor').classList.contains('comfy-mode')&&!document.querySelector('#comfyui-tools').hidden&&document.querySelector('#comfyui-tools').open");
  await evaluate("window.qaComfyAnimation=document.querySelector('.provider-editor').getAnimations({subtree:true}).find(animation=>animation.animationName==='comfy-provider-sweep')");
  await field('#provider-name','My workflow service');
  await check('ordinary edits do not replay the mode transition', "document.querySelector('.provider-editor').getAnimations({subtree:true}).includes(qaComfyAnimation)");
  await capture('provider-comfy-desktop');
  await click('[data-provider-view="workflow"]');
  await check('ComfyUI has its own workflow pane, separate from API credentials and model policies', "!document.querySelector('#provider-view-workflow').hidden&&document.querySelector('#provider-view-connection').hidden&&document.querySelector('#provider-view-models').hidden");
  await click('[data-provider-view="connection"]');
  await field('#provider-preset','custom');
  await field('#provider-url','http://127.0.0.1:7999/v1'); await field('#provider-media-url','http://127.0.0.1:7999/media/v1');
  await field('#provider-key-action','replace'); await field('#provider-key','PANEL_KEY_NOT_A_REAL_CREDENTIAL');
  await field('#provider-preset','comfyui');
  await check('entering ComfyUI clears an unrelated media override and uses workflow authentication', "document.querySelector('#provider-media-url').value===''&&document.querySelector('#provider-auth').value==='none'&&document.querySelector('#provider-protocol').value==='comfyui'");
  await field('#provider-preset','custom');
  await check('returning to custom restores the actual API draft and pending credential, and fully exits ComfyUI', "document.querySelector('#provider-protocol').value==='openai-images'&&document.querySelector('#provider-url').value==='http://127.0.0.1:7999/v1'&&document.querySelector('#provider-media-url').value==='http://127.0.0.1:7999/media/v1'&&document.querySelector('#provider-auth').value==='bearer'&&document.querySelector('#provider-key-action').value==='replace'&&document.querySelector('#provider-key').value==='PANEL_KEY_NOT_A_REAL_CREDENTIAL'&&document.querySelector('#provider-comfy-mode').hidden&&document.querySelector('#comfyui-tools').hidden&&!document.querySelector('.provider-editor').classList.contains('comfy-mode')");
  await field('#provider-preset','comfyui');
  await field('#provider-preset','openai');
  await check('an explicit OpenAI preset also exits ComfyUI and restores bearer authentication', "document.querySelector('#provider-comfy-mode').hidden&&!document.querySelector('.provider-editor').classList.contains('comfy-mode')&&document.querySelector('#comfyui-tools').hidden&&document.querySelector('#provider-url').value==='https://api.openai.com/v1'&&document.querySelector('#provider-auth').value==='bearer'&&document.querySelector('#provider-media-url').value===''");
  await click('#provider-advanced>summary'); await field('#provider-protocol','comfyui');
  await check('direct protocol selection also starts the mode accent', "document.querySelector('.provider-editor').getAnimations({subtree:true}).some(animation=>animation.animationName==='comfy-provider-sweep')");
  await check('direct protocol selection keeps the quick selection in sync', "document.querySelector('#provider-preset').value==='comfyui'");
  for (const width of [390,320]) { await dimensions(width); await measure('provider-comfy-'+width); }
  await capture('provider-comfy-320');
  await cdp('Emulation.setEmulatedMedia',{features:[{name:'prefers-reduced-motion',value:'reduce'}]});
  await field('#provider-preset','openai'); await field('#provider-preset','comfyui');
  await check('reduced motion keeps the mode cue and disables moving accents', "!document.querySelector('#provider-comfy-mode').hidden&&getComputedStyle(document.querySelector('.provider-editor'),'::after').animationName==='none'");
  await cdp('Emulation.setEmulatedMedia',{features:[]}); await dimensions(1366,900);
  await click('#provider-save'); await wait(()=>evaluate("document.querySelector('#provider-state').textContent==='已保存'&&!document.querySelector('#provider-fields').disabled"),'persist fixture ComfyUI connection');
  await click('#providers-refresh'); await wait(()=>evaluate("!document.querySelector('#provider-fields').disabled"),'reload saved workflow mode');
  await check('a saved ComfyUI provider reopens with matching quick selection and protocol', "document.querySelector('#provider-preset').value==='comfyui'&&document.querySelector('#provider-protocol').value==='comfyui'");
  await field('#provider-preset','custom');
  await check('without an earlier API draft, custom starts an empty API connection rather than reusing the ComfyUI endpoint', "document.querySelector('#provider-protocol').value==='openai-images'&&document.querySelector('#provider-url').value===''&&document.querySelector('#provider-media-url').value===''&&document.querySelector('#provider-auth').value==='bearer'&&document.querySelector('#provider-key').value===''");
  await click('#provider-back');
  await check('returning to the overview asks before discarding an unsaved provider draft', "!document.querySelector('#provider-close-confirm').hidden&&!document.querySelector('#provider-editor').hidden");
  await click('#provider-close-cancel');
  await check('canceling the return preserves the draft and does not save it', "document.querySelector('#provider-close-confirm').hidden&&document.querySelector('#provider-url').value===''");
  await click('#provider-back'); await click('#provider-close-discard');
  await check('explicit discard returns to a real provider summary without saving the changed protocol', "!document.querySelector('#providers-overview').hidden&&document.querySelector('#provider-editor').hidden&&document.querySelectorAll('#providers-list .service-card').length===1&&document.querySelector('#providers-list').textContent.includes('ComfyUI 工作流')");
  await capture('provider-overview-desktop');

  const requestsBefore = report.requests.length;
  await cdp('Page.reload'); await wait(connected, 'second retained login');
  await click('#connections-tab'); await check('deleted connections remain absent after a real page refresh', "document.querySelectorAll('#connections-list .connection-item').length===0");
  assert(report.requests.slice(requestsBefore).every(item=>item.method==='GET'), 'refresh must not recreate a connection or resubmit media');
  result.checks.push('refresh after editing neither writes configuration nor resubmits work');
  await click('#disconnect');
  await check('explicit logout clears the saved login', `!document.querySelector('#connection').hidden&&sessionStorage.getItem(${JSON.stringify(storageKey)})===null`);
  const loggedOutStart=report.requests.length;
  await cdp('Page.reload'); await wait(()=>evaluate("Boolean(document.documentElement.dataset.theme)"),'logged out reload');
  await check('logout stays logged out after refresh', "!document.querySelector('#connection').hidden&&document.querySelector('#workspace').hidden");
  assert(!report.requests.slice(loggedOutStart).some(item=>item.url===session.origin+'/api/v0/session'));

  await chooseToken(tokenFile()); await wait(connected,'login before restart');
  session=await restart(config); await cdp('Page.reload');
  await wait(()=>evaluate("!document.querySelector('#connection').hidden&&document.querySelector('#feedback').textContent.includes('失效')"),'old token rejected after restart');
  await check('a restarted service invalidates and removes the old saved token', `sessionStorage.getItem(${JSON.stringify(storageKey)})===null&&document.querySelector('#token').value===''`);
  await evaluate(`sessionStorage.setItem(${JSON.stringify(storageKey)},'INVALID_TOKEN_FIXTURE')`);
  await cdp('Page.reload'); await wait(()=>evaluate("Boolean(document.documentElement.dataset.theme)"),'invalid cache mount');
  await check('invalid saved login is discarded without exposing its contents', `sessionStorage.getItem(${JSON.stringify(storageKey)})===null&&!document.body.textContent.includes('INVALID_TOKEN_FIXTURE')&&!document.querySelector('#connection').hidden`);

  await cdp('Page.addScriptToEvaluateOnNewDocument',{source:`for(const method of ['getItem','setItem','removeItem']){const original=Storage.prototype[method];Storage.prototype[method]=function(key,...args){if(key===${JSON.stringify(storageKey)})throw new DOMException('Storage disabled for controlled check','SecurityError');return original.call(this,key,...args)}}`});
  await cdp('Page.reload'); await wait(()=>evaluate("Boolean(document.documentElement.dataset.theme)"),'blocked storage mount');
  await chooseToken(tokenFile()); await wait(connected,'manual login with blocked storage');
  await check('blocked session storage keeps manual login usable and explains refresh limits', "!document.querySelector('#session-notice').hidden&&document.querySelector('#session-notice').textContent.includes('刷新')");
  await click('#disconnect');
  await check('logout reports an unavailable credential clear instead of claiming persistence', "!document.querySelector('#connection').hidden&&!document.querySelector('#session-notice').hidden");
  assert(!report.requests.some(item=>/\/api\/v0\/(generations|images|runs\/[^/]+\/continue)(?:$|\?)/.test(new URL(item.url).pathname)&&item.method==='POST'));
  result.checks.push('all feedback scenarios submit zero media');
  result.status='passed'; save();
}
